1 | <!DOCTYPE html>
2 | <html lang="en">
3 | <head>
4 | <meta charset="utf-8">
5 | <meta name="viewport" content="width=device-width, initial-scale=1">
6 | <title>RegulatoryGuard AI — User Guide</title>
7 | <link rel="preconnect" href="https://fonts.googleapis.com">
8 | <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
9 | <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
10 | <style>
11 |   :root {
12 |     --brand-dark:       #0A192F;
13 |     --brand-blue:       #0284C7;
14 |     --brand-light-blue: #E0F2FE;
15 |     --bg-surface:       #F8FAFC;
16 |     --bg-card:          #FFFFFF;
17 |     --text-primary:     #0F172A;
18 |     --text-secondary:   #475569;
19 |     --line:             #E2E8F0;
20 |     --status-green:     #10B981;
21 |     --status-yellow:    #F59E0B;
22 |     --status-red:       #EF4444;
23 |   }
24 | 
25 |   *, *::before, *::after { box-sizing: border-box; }
26 | 
27 |   body {
28 |     margin: 0;
29 |     background: #F1F5F9;
30 |     color: var(--text-secondary);
31 |     font-family: 'Plus Jakarta Sans', 'Segoe UI', Helvetica, Arial, sans-serif;
32 |     font-size: 15px;
33 |     line-height: 1.7;
34 |   }
35 | 
36 |   /* ─── Header ─────────────────────────────────────────── */
37 |   header {
38 |     background: var(--brand-dark);
39 |     padding: 56px 0 52px;
40 |     position: relative;
41 |     overflow: hidden;
42 |   }
43 |   header::after {
44 |     content: "";
45 |     position: absolute; inset: 0;
46 |     background:
47 |       radial-gradient(120% 90% at 8% 110%, rgba(2,132,199,.35) 0%, rgba(2,132,199,0) 55%),
48 |       radial-gradient(80% 100% at 95% -5%, rgba(15,23,42,.7) 0%, rgba(15,23,42,0) 60%);
49 |     pointer-events: none;
50 |   }
51 |   header .wrap { position: relative; z-index: 1; }
52 |   header .badge-tag {
53 |     display: inline-block;
54 |     background: rgba(2,132,199,.2);
55 |     color: #7DD3FC;
56 |     border: 1px solid rgba(2,132,199,.35);
57 |     border-radius: 999px;
58 |     padding: 4px 14px;
59 |     font-size: 12px;
60 |     font-weight: 600;
61 |     letter-spacing: .06em;
62 |     text-transform: uppercase;
63 |     margin-bottom: 18px;
64 |   }
65 |   header h1 {
66 |     margin: 0 0 10px;
67 |     font-size: clamp(28px, 4vw, 46px);
68 |     font-weight: 800;
69 |     color: #fff;
70 |     letter-spacing: -.025em;
71 |     line-height: 1.1;
72 |   }
73 |   header p {
74 |     margin: 0;
75 |     color: #94A3B8;
76 |     font-size: 16px;
77 |     max-width: 56ch;
78 |   }
79 | 
80 |   /* ─── Layout ─────────────────────────────────────────── */
81 |   .wrap { max-width: 900px; margin: 0 auto; padding: 0 28px; }
82 | 
83 |   .layout { display: grid; grid-template-columns: 220px 1fr; gap: 32px; padding: 40px 0 60px; align-items: start; }
84 | 
85 |   /* ─── TOC sidebar ─────────────────────────────────────── */
86 |   .toc {
87 |     position: sticky;
88 |     top: 24px;
89 |     background: var(--bg-card);
90 |     border: 1px solid var(--line);
91 |     border-radius: 14px;
92 |     padding: 18px 20px;
93 |   }
94 |   .toc-title {
95 |     font-size: 11px;
96 |     font-weight: 700;
97 |     text-transform: uppercase;
98 |     letter-spacing: .1em;
99 |     color: var(--text-secondary);
100 |     margin: 0 0 12px;
101 |   }
102 |   .toc ol {
103 |     margin: 0; padding: 0 0 0 18px;
104 |     font-size: 13px;
105 |     line-height: 2;
106 |     color: var(--brand-blue);
107 |   }
108 |   .toc ol li a {
109 |     color: var(--text-secondary);
110 |     text-decoration: none;
111 |     font-weight: 500;
112 |     transition: color .15s;
113 |   }
114 |   .toc ol li a:hover { color: var(--brand-blue); }
115 | 
116 |   /* ─── Main content ────────────────────────────────────── */
117 |   .content { min-width: 0; }
118 | 
119 |   h2 {
120 |     font-size: 22px;
121 |     font-weight: 800;
122 |     color: var(--text-primary);
123 |     margin: 48px 0 10px;
124 |     letter-spacing: -.02em;
125 |     padding-bottom: 10px;
126 |     border-bottom: 2px solid var(--line);
127 |   }
128 |   h2:first-child { margin-top: 0; }
129 |   h3 {
130 |     font-size: 16px;
131 |     font-weight: 700;
132 |     color: var(--text-primary);
133 |     margin: 24px 0 6px;
134 |   }
135 |   p { margin: 0 0 12px; }
136 |   ul, ol { margin: 0 0 14px; padding-left: 22px; }
137 |   li { margin-bottom: 5px; }
138 | 
139 |   /* ─── Code blocks ─────────────────────────────────────── */
140 |   code {
141 |     font-family: 'Menlo', 'Consolas', 'Monaco', monospace;
142 |     font-size: 13px;
143 |     background: rgba(15,23,42,.07);
144 |     color: #0F172A;
145 |     padding: 2px 6px;
146 |     border-radius: 5px;
147 |   }
148 |   pre {
149 |     background: var(--brand-dark);
150 |     color: #E2E8F0;
151 |     border-radius: 10px;
152 |     padding: 18px 20px;
153 |     overflow-x: auto;
154 |     font-size: 13.5px;
155 |     line-height: 1.6;
156 |     margin: 10px 0 18px;
157 |   }
158 |   pre code {
159 |     background: transparent;
160 |     color: inherit;
161 |     padding: 0;
162 |     border-radius: 0;
163 |   }
164 | 
165 |   /* ─── Info / tip / warning panels ───────────────────────*/
166 |   .panel {
167 |     border-radius: 10px;
168 |     padding: 14px 18px;
169 |     margin: 14px 0;
170 |     font-size: 14px;
171 |     line-height: 1.6;
172 |     border-left: 4px solid;
173 |   }
174 |   .panel.info    { background: var(--brand-light-blue); border-color: var(--brand-blue); color: #0C4A6E; }
175 |   .panel.tip     { background: rgba(16,185,129,.08);    border-color: var(--status-green); color: #064E3B; }
176 |   .panel.warning { background: rgba(245,158,11,.09);    border-color: var(--status-yellow); color: #78350F; }
177 |   .panel.danger  { background: rgba(239,68,68,.08);     border-color: var(--status-red); color: #7F1D1D; }
178 | 
179 |   /* ─── Step list ───────────────────────────────────────── */
180 |   .step-list { list-style: none; padding: 0; margin: 0 0 18px; }
181 |   .step-list li {
182 |     display: flex; gap: 14px; align-items: flex-start;
183 |     padding: 12px 0; border-bottom: 1px solid var(--line);
184 |     font-size: 14px;
185 |   }
186 |   .step-list li:last-child { border-bottom: none; }
187 |   .step-num {
188 |     min-width: 28px; height: 28px;
189 |     background: var(--brand-blue); color: #fff;
190 |     border-radius: 50%;
191 |     font-size: 13px; font-weight: 700;
192 |     display: flex; align-items: center; justify-content: center;
193 |     flex-shrink: 0; margin-top: 1px;
194 |   }
195 | 
196 |   /* ─── Traffic-light badges ────────────────────────────── */
197 |   .badge {
198 |     display: inline-flex; align-items: center; gap: 7px;
199 |     padding: 4px 12px; border-radius: 999px;
200 |     font-size: 13px; font-weight: 600;
